// SPDX-License-Identifier: GPL-3.0
pragma solidity =0.6.12;

import "./interfaces/ICASwapFactory.sol";
import "./CASwapPair.sol";
import "./abstract/Whitelistable.sol";

contract CASwapFactory is ICASwapFactory, Whitelistable {
  /// @dev 10000 = 100% of the swap input. The cap is the maximum the admin can set.
  uint256 public constant MAX_FEE_BPS = 10000;

  address public feeToSetter;
  /// @dev Pending feeToSetter waiting to accept the two-step admin handover.
  address public pendingFeeToSetter;
  address public router;

  mapping(address => mapping(address => address)) public override getPair;
  address[] public override allPairs;

  /// @dev Fee receiver for a trading pair.
  mapping(address => mapping(address => address)) public override pairFeeReceivers;

  /// @dev Swap fee (in bps) for tokenIn -> tokenOut.
  mapping(address => mapping(address => uint256)) public override pairFeeBps;
  mapping(address => bool) public isPair;

  constructor(address _feeToSetter) public {
    require(_feeToSetter != address(0), "CASwapFactory: ZERO_FEE_TO_SETTER");
    feeToSetter = _feeToSetter;
  }

  /**
   * @dev Whitelistable admin hook; backs the inherited `onlyAdmin` modifier.
   */
  function _authorize() internal view override {
    require(msg.sender == feeToSetter, "CASwapFactory: FORBIDDEN");
  }

  function allPairsLength() external view override returns (uint256) {
    return allPairs.length;
  }

  function createPair(address tokenA, address tokenB) external override returns (address pair) {
    require(router != address(0), "CASwapFactory: ROUTER_NOT_SET");
    require(tokenA != tokenB, "CASwapFactory: IDENTICAL_ADDRESSES");
    (address token0, address token1) = tokenA < tokenB ? (tokenA, tokenB) : (tokenB, tokenA);
    require(token0 != address(0), "CASwapFactory: ZERO_ADDRESS");
    require(getPair[token0][token1] == address(0), "CASwapFactory: PAIR_EXISTS");
    bytes memory bytecode = type(CASwapPair).creationCode;
    bytes32 salt = keccak256(abi.encodePacked(token0, token1));
    assembly {
      pair := create2(0, add(bytecode, 32), mload(bytecode), salt)
    }
    CASwapPair(pair).initialize(token0, token1, router);
    getPair[token0][token1] = pair;
    getPair[token1][token0] = pair;  // populate mapping in the reverse direction
    allPairs.push(pair);
    isPair[pair] = true;
    emit PairCreated(token0, token1, pair, allPairs.length);
  }

  /**
   * @dev Start a two-step transfer of fee, Router and whitelist admin rights.
   * @dev The current feeToSetter keeps full admin power until acceptFeeToSetter is called.
   * @dev Pass address(0) to cancel a previously started transfer.
   * @param newFeeToSetter Address that will become feeToSetter once it calls acceptFeeToSetter.
   */
  function setFeeToSetter(address newFeeToSetter) external onlyAdmin {
    pendingFeeToSetter = newFeeToSetter;
    emit FeeToSetterTransferStarted(feeToSetter, newFeeToSetter);
  }

  /**
   * @dev Complete the two-step admin handover; callable only by the pending feeToSetter.
   */
  function acceptFeeToSetter() external {
    require(msg.sender == pendingFeeToSetter, "CASwapFactory: NOT_PENDING_FEE_TO_SETTER");

    address oldFeeToSetter = feeToSetter;
    feeToSetter = pendingFeeToSetter;
    delete pendingFeeToSetter;

    emit FeeToSetterTransferred(oldFeeToSetter, feeToSetter);
  }

  /**
   * @dev Set Router once. Existing and future Pairs trust this Router via onlyRouter.
   * @param _router Router address.
   */
  function setRouter(address _router) external onlyAdmin {
    require(_router != address(0), "CASwapFactory: ZERO_ADDRESS");
    require(router == address(0), "CASwapFactory: ROUTER_ALREADY_SET");

    router = _router;
    emit RouterSet(_router);
  }

  /**
   * @dev Set fee receiver for a pair; stored symmetrically for both token orders.
   * @param receiver Address that receives custom swap fees.
   */
  function setPairFeeReceiver(address tokenA, address tokenB, address receiver) external onlyAdmin {
    require(receiver != address(0), "CASwapFactory: ZERO_ADDRESS");

    (address token0, address token1) = tokenA < tokenB ? (tokenA, tokenB) : (tokenB, tokenA);
    pairFeeReceivers[token0][token1] = receiver;
    pairFeeReceivers[token1][token0] = receiver;

    emit PairFeeReceiverSet(tokenA, tokenB, receiver);
  }

  /**
   * @dev Set directional swap fee in basis points for tokenIn -> tokenOut.
   * @param feeBps Fee in bps; capped by MAX_FEE_BPS.
   */
  function setPairFeeBps(address tokenIn, address tokenOut, uint256 feeBps) external onlyAdmin {
    require(feeBps <= MAX_FEE_BPS, "CASwapFactory: FEE_TOO_HIGH");

    if (feeBps > 0) {
      require(pairFeeReceivers[tokenIn][tokenOut] != address(0), "CASwapFactory: FEE_RECEIVER_NOT_SET");
    }

    pairFeeBps[tokenIn][tokenOut] = feeBps;
    emit PairFeeBpsSet(tokenIn, tokenOut, feeBps);
  }

  /**
   * @dev Admin entry for Pair.sync because Pair.sync only accepts the Factory.
   * @param pair Pair address registered by this Factory.
   */
  function sync(address pair) external onlyAdmin {
    require(isPair[pair], "CASwapFactory: INVALID_PAIR");

    CASwapPair(pair).sync();
  }

  /**
   * @dev Resolve effective fee-exempt status from Whitelistable.
   */
  function isFeeExempt(address user) public view override(ICASwapFactory, Whitelistable) returns (bool) {
    return super.isFeeExempt(user);
  }

  /**
   * @dev Resolve effective LP allowlist status from Whitelistable.
   */
  function isLpAllowed(address user) public view override(ICASwapFactory, Whitelistable) returns (bool) {
    return super.isLpAllowed(user);
  }
}

