pragma solidity =0.6.12;

// a library for performing various math operations

library Math {
  function min(uint256 x, uint256 y) internal pure returns (uint256 z) {
    z = x < y ? x : y;
  }

  // babylonian method (https://en.wikipedia.org/wiki/Methods_of_computing_square_roots#Babylonian_method)
  function sqrt(uint256 y) internal pure returns (uint256 z) {
    if (y > 3) {
      z = y;
      uint256 x = y / 2 + 1;
      while (x < z) {
        z = x;
        x = (y / x + x) / 2;
      }
    } else if (y != 0) {
      z = 1;
    }
  }
}

// SPDX-License-Identifier: GPL-3.0
pragma solidity =0.6.12;

// a library for performing overflow-safe math, courtesy of DappHub (https://github.com/dapphub/ds-math)

library SafeMath {
  function add(uint256 x, uint256 y) internal pure returns (uint256 z) {
    require((z = x + y) >= x, "ds-math-add-overflow");
  }

  function sub(uint256 x, uint256 y) internal pure returns (uint256 z) {
    require((z = x - y) <= x, "ds-math-sub-underflow");
  }

  function mul(uint256 x, uint256 y) internal pure returns (uint256 z) {
    require(y == 0 || (z = x * y) / y == x, "ds-math-mul-overflow");
  }
}

// SPDX-License-Identifier: GPL-3.0
pragma solidity =0.6.12;

import "./libraries/SafeMath.sol";
import "./interfaces/ICASwapLP.sol";

contract CASwapLP is ICASwapLP {
  using SafeMath for uint256;

  string public constant override name = "CASwap LP Token";
  string public constant override symbol = "CA-LP";
  uint8 public constant override decimals = 18;
  uint256 public override totalSupply;
  mapping(address => uint256) public override balanceOf;
  mapping(address => mapping(address => uint256)) public override allowance;

  bytes32 public override DOMAIN_SEPARATOR;
  // keccak256("Permit(address owner,address spender,uint256 value,uint256 nonce,uint256 deadline)")
  bytes32 public constant override PERMIT_TYPEHASH = 0x6e71edae12b1b97f4d1f60370fef10105fa2faae0126114a169c64845d6126c9;
  mapping(address => uint256) public override nonces;

  constructor() public {
    uint256 chainId;
    assembly {
      chainId := chainid()
    }
    DOMAIN_SEPARATOR = keccak256(
      abi.encode(
        keccak256("EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)"),
        keccak256(bytes(name)),
        keccak256(bytes("1")),
        chainId,
        address(this)
      )
    );
  }

  function _mint(address to, uint256 value) internal {
    totalSupply = totalSupply.add(value);
    balanceOf[to] = balanceOf[to].add(value);
    emit Transfer(address(0), to, value);
  }

  function _burn(address from, uint256 value) internal {
    balanceOf[from] = balanceOf[from].sub(value);
    totalSupply = totalSupply.sub(value);
    emit Transfer(from, address(0), value);
  }

  function _approve(address owner, address spender, uint256 value) private {
    allowance[owner][spender] = value;
    emit Approval(owner, spender, value);
  }

  function _transfer(address from, address to, uint256 value) private {
    balanceOf[from] = balanceOf[from].sub(value);
    balanceOf[to] = balanceOf[to].add(value);
    emit Transfer(from, to, value);
  }

  function approve(address spender, uint256 value) external override returns (bool) {
    _approve(msg.sender, spender, value);
    return true;
  }

  function transfer(address to, uint256 value) external override returns (bool) {
    _transfer(msg.sender, to, value);
    return true;
  }

  function transferFrom(address from, address to, uint256 value) external override returns (bool) {
    // Infinite allowance (uint256(-1)) is not decremented; matches V2 behavior.
    if (allowance[from][msg.sender] != uint256(-1)) {
      allowance[from][msg.sender] = allowance[from][msg.sender].sub(value);
    }
    _transfer(from, to, value);
    return true;
  }

  function permit(
    address owner,
    address spender,
    uint256 value,
    uint256 deadline,
    uint8 v,
    bytes32 r,
    bytes32 s
  ) external override {
    require(deadline >= block.timestamp, "CASwapLP: EXPIRED");
    bytes32 digest = keccak256(
      abi.encodePacked(
        "\x19\x01",
        DOMAIN_SEPARATOR,
        keccak256(abi.encode(PERMIT_TYPEHASH, owner, spender, value, nonces[owner]++, deadline))
      )
    );
    address recoveredAddress = ecrecover(digest, v, r, s);
    require(recoveredAddress != address(0) && recoveredAddress == owner, "CASwapLP: INVALID_SIGNATURE");
    _approve(owner, spender, value);
  }
}

// SPDX-License-Identifier: GPL-3.0
pragma solidity =0.6.12;

import "./interfaces/ICASwapPair.sol";
import "./CASwapLP.sol";
import "./libraries/Math.sol";
import "./libraries/UQ112x112.sol";
import "./interfaces/IERC20.sol";
import "./interfaces/ICASwapFactory.sol";
import "./interfaces/ICASwapCallee.sol";

contract CASwapPair is ICASwapPair, CASwapLP {
  using SafeMath for uint256;
  using UQ112x112 for uint224;

  uint256 public constant override MINIMUM_LIQUIDITY = 10**3;
  bytes4 private constant SELECTOR = bytes4(keccak256(bytes("transfer(address,uint256)")));

  address public override factory;
  address public override token0;
  address public override token1;
  address public router;

  uint112 private reserve0;             // uses single storage slot, accessible via getReserves
  uint112 private reserve1;             // uses single storage slot, accessible via getReserves
  uint32 private blockTimestampLast;    // uses single storage slot, accessible via getReserves

  uint256 public override price0CumulativeLast;
  uint256 public override price1CumulativeLast;

  uint256 private unlocked = 1;
  modifier lock() {
    require(unlocked == 1, "CASwapPair: LOCKED");
    unlocked = 0;
    _;
    unlocked = 1;
  }

  modifier onlyRouter() {
    require(msg.sender == router, "CASwapPair: ONLY_ROUTER");
    _;
  }

  modifier onlyFactory() {
    require(msg.sender == factory, "CASwapPair: ONLY_FACTORY");
    _;
  }

  function getReserves() public view override returns (uint112 _reserve0, uint112 _reserve1, uint32 _blockTimestampLast) {
    _reserve0 = reserve0;
    _reserve1 = reserve1;
    _blockTimestampLast = blockTimestampLast;
  }

  function _safeTransfer(
    address token,
    address to,
    uint256 value
  ) private {
    (bool success, bytes memory data) = token.call(abi.encodeWithSelector(SELECTOR, to, value));
    require(success && (data.length == 0 || abi.decode(data, (bool))), "CASwapPair: TRANSFER_FAILED");
  }

  constructor() public {
    factory = msg.sender;
  }

  /**
   * @dev Initialize immutable Pair state once during Factory.createPair.
   * @param _router Router allowed to call mint, burn and swap.
   */
  function initialize(address _token0, address _token1, address _router) external override {
    require(msg.sender == factory, "CASwapPair: FORBIDDEN"); // sufficient check
    require(_token0 != address(0), "CASwapPair: ZERO_TOKEN");
    require(_token1 != address(0), "CASwapPair: ZERO_TOKEN");

    token0 = _token0;
    token1 = _token1;
    router = _router;
  }

  function _update(
    uint256 balance0,
    uint256 balance1,
    uint112 _reserve0,
    uint112 _reserve1
  ) private {
    require(balance0 <= uint112(-1) && balance1 <= uint112(-1), "CASwapPair: OVERFLOW");
    uint32 blockTimestamp = uint32(block.timestamp % 2**32);
    uint32 timeElapsed = blockTimestamp - blockTimestampLast; // overflow is desired
    if (timeElapsed > 0 && _reserve0 != 0 && _reserve1 != 0) {
      // * never overflows, and + overflow is desired
      price0CumulativeLast += uint256(UQ112x112.encode(_reserve1).uqdiv(_reserve0)) * timeElapsed;
      price1CumulativeLast += uint256(UQ112x112.encode(_reserve0).uqdiv(_reserve1)) * timeElapsed;
    }
    reserve0 = uint112(balance0);
    reserve1 = uint112(balance1);
    blockTimestampLast = blockTimestamp;
    emit Sync(reserve0, reserve1);
  }

  /**
   * @dev Mint LP from token surplus already transferred into the Pair by the Router.
   * @param to Receiver of minted LP tokens.
   */
  function mint(address to) external override lock onlyRouter returns (uint256 liquidity) {
    (uint112 _reserve0, uint112 _reserve1, ) = getReserves(); // gas savings
    uint256 balance0 = IERC20(token0).balanceOf(address(this));
    uint256 balance1 = IERC20(token1).balanceOf(address(this));
    uint256 amount0 = balance0.sub(_reserve0);
    uint256 amount1 = balance1.sub(_reserve1);

    uint256 _totalSupply = totalSupply; // gas savings, must be defined here since totalSupply can update in _mint
    if (_totalSupply == 0) {
      liquidity = Math.sqrt(amount0.mul(amount1)).sub(MINIMUM_LIQUIDITY);
      _mint(address(0), MINIMUM_LIQUIDITY); // permanently lock the first MINIMUM_LIQUIDITY tokens
    } else {
      liquidity = Math.min(amount0.mul(_totalSupply) / _reserve0, amount1.mul(_totalSupply) / _reserve1);
    }
    require(liquidity > 0, "CASwapPair: INSUFFICIENT_LIQUIDITY_MINTED");
    _mint(to, liquidity);

    _update(balance0, balance1, _reserve0, _reserve1);
    emit Mint(msg.sender, amount0, amount1);
  }

  /**
   * @dev Burn LP held by this Pair and send proportional token balances to receiver.
   * @param to Receiver of token0 and token1 outputs.
   */
  function burn(address to) external override lock onlyRouter returns (uint256 amount0, uint256 amount1) {
    (uint112 _reserve0, uint112 _reserve1, ) = getReserves();   // gas savings
    address _token0 = token0;                                   // gas savings
    address _token1 = token1;                                   // gas savings
    uint256 balance0 = IERC20(_token0).balanceOf(address(this));
    uint256 balance1 = IERC20(_token1).balanceOf(address(this));
    uint256 liquidity = balanceOf[address(this)];

    uint256 _totalSupply = totalSupply; // gas savings, must be defined here since totalSupply can update in _burn
    amount0 = liquidity.mul(balance0) / _totalSupply; // using balances ensures pro-rata distribution
    amount1 = liquidity.mul(balance1) / _totalSupply; // using balances ensures pro-rata distribution
    require(amount0 > 0 && amount1 > 0, "CASwapPair: INSUFFICIENT_LIQUIDITY_BURNED");
    _burn(address(this), liquidity);
    _safeTransfer(_token0, to, amount0);
    _safeTransfer(_token1, to, amount1);
    balance0 = IERC20(_token0).balanceOf(address(this));
    balance1 = IERC20(_token1).balanceOf(address(this));

    _update(balance0, balance1, _reserve0, _reserve1);
    emit Burn(msg.sender, amount0, amount1, to);
  }

  /**
   * @dev Optimistic constant-product swap with optional directional fee.
   * @param addresses addresses[0] is recipient; addresses[1] is original payer for fee checks.
   * @param data Optional flash-swap callback payload.
   */
  function swap(
    uint256 amount0Out,
    uint256 amount1Out,
    address[2] memory addresses,
    bytes calldata data
  ) external override lock onlyRouter {
    require(amount0Out > 0 || amount1Out > 0, "CASwapPair: INSUFFICIENT_OUTPUT_AMOUNT");
    (uint112 _reserve0, uint112 _reserve1, ) = getReserves(); // gas savings
    require(amount0Out < _reserve0 && amount1Out < _reserve1, "CASwapPair: INSUFFICIENT_LIQUIDITY");

    uint256 balance0;
    uint256 balance1;

    {
      address to = addresses[0];
      // scope for _token{0,1}, avoids stack too deep errors
      address _token0 = token0;
      address _token1 = token1;
      require(to != _token0 && to != _token1, "CASwapPair: INVALID_TO");
      if (amount0Out > 0) _safeTransfer(_token0, to, amount0Out); // optimistically transfer tokens
      if (amount1Out > 0) _safeTransfer(_token1, to, amount1Out); // optimistically transfer tokens
      if (data.length > 0) ICASwapCallee(to).caSwapCall(msg.sender, amount0Out, amount1Out, data);
      balance0 = IERC20(_token0).balanceOf(address(this));
      balance1 = IERC20(_token1).balanceOf(address(this));
    }
    uint256 amount0In = balance0 > _reserve0 - amount0Out ? balance0 - (_reserve0 - amount0Out) : 0;
    uint256 amount1In = balance1 > _reserve1 - amount1Out ? balance1 - (_reserve1 - amount1Out) : 0;
    require(amount0In > 0 || amount1In > 0, "CASwapPair: INSUFFICIENT_INPUT_AMOUNT");
    require(amount0Out == 0 || amount1Out == 0, "CASwapPair: ONLY_ONE_DIRECTION");

    {
      ICASwapFactory _factory = ICASwapFactory(factory);
      address feeReceiver = _factory.pairFeeReceivers(token0, token1);

      // Directional fee: tokenIn -> tokenOut may differ from the reverse route.
      uint256 feeBps = amount0Out > 0
        ? _factory.pairFeeBps(token1, token0)
        : _factory.pairFeeBps(token0, token1);

      bool feeExempt = _factory.isFeeExempt(addresses[1]);
      if (!feeExempt && feeReceiver != address(0) && feeBps > 0) {
        require(feeReceiver != address(this), "CASwapPair: INVALID_FEE_RECEIVER");

        // Custom fee is paid from input before the K invariant is checked.
        uint256 fee0 = amount0In.mul(feeBps) / 10000;
        uint256 fee1 = amount1In.mul(feeBps) / 10000;

        if (fee0 > 0) {
          _safeTransfer(token0, feeReceiver, fee0);
          balance0 = balance0.sub(fee0);
          amount0In = amount0In.sub(fee0);
        }

        if (fee1 > 0) {
          _safeTransfer(token1, feeReceiver, fee1);
          balance1 = balance1.sub(fee1);
          amount1In = amount1In.sub(fee1);
        }
      }

      // Use a 10000 scale because pair fees are stored in basis points.
      uint256 balance0Adjusted = balance0.mul(10000);
      uint256 balance1Adjusted = balance1.mul(10000);
      require(balance0Adjusted.mul(balance1Adjusted) >= uint256(_reserve0).mul(_reserve1).mul(10000**2), "CASwapPair: K");
    }

    _update(balance0, balance1, _reserve0, _reserve1);
    emit Swap(msg.sender, amount0In, amount1In, amount0Out, amount1Out, addresses[0]);
  }

  /**
   * @dev Sweep token balances above reserves; does not change reserves.
   * @param to Receiver of the excess balances.
   */
  function skim(address to) external override lock {
    address _token0 = token0; // gas savings
    address _token1 = token1; // gas savings
    _safeTransfer(_token0, to, IERC20(_token0).balanceOf(address(this)).sub(reserve0));
    _safeTransfer(_token1, to, IERC20(_token1).balanceOf(address(this)).sub(reserve1));
  }

  /**
   * @dev Force reserves to match balances. Restricted to Factory.sync.
   */
  function sync() external override lock onlyFactory {
    _update(IERC20(token0).balanceOf(address(this)), IERC20(token1).balanceOf(address(this)), reserve0, reserve1);
  }
}

