pragma solidity =0.6.12;

abstract contract Whitelistable {

    mapping(address => bool) public feeExempt;
    mapping(address => bool) public lpAllowlist;

    /**
     * @dev If false, feeExempt is ignored and all users pay normal pair fees.
     */
    bool public feeExemptOn;

    /**
     * @dev If false, lpAllowlist is ignored and anyone can manage liquidity.
     */
    bool public lpAllowlistOn;

    /**
     * @dev Upper bound on the address count accepted by {setFeeExemptBatch}.
     * Kept well under the block gas limit so a full batch can never become
     * unminable: ~25k gas per entry * 100 ~= 2.5M gas.
     */
    uint16 public constant MAX_BATCH_SIZE_LIMIT = 100;

    event FeeExemptSet(address indexed user, bool allowed);
    event LpAllowlistSet(address indexed user, bool allowed);
    event FeeExemptOnSet(bool on);
    event LpAllowlistOnSet(bool on);

    constructor() internal {
        feeExemptOn = true;
        lpAllowlistOn = true;
    }

    /**
     * @dev Implemented by the child contract to define the admin.
     */
    function _authorize() internal view virtual;

    modifier onlyAdmin() {
        _authorize();
        _;
    }

    /**
     * @dev Set whether a user skips pair swap fees while feeExemptOn is true.
     * @param user User address.
     * @param allowed Fee-exempt flag.
     */
    function setFeeExempt(address user, bool allowed) external onlyAdmin {
        _setFeeExempt(user, allowed);
    }

    /**
     * @dev Batch {setFeeExempt}: applies `allowed` to every address in `users`.
     * The shared guard rejects zero addresses, no-op entries, and duplicates.
     * @param users Addresses to update (1..MAX_BATCH_SIZE_LIMIT).
     * @param allowed Fee-exempt flag applied to all of them.
     */
    function setFeeExemptBatch(address[] calldata users, bool allowed) external onlyAdmin {
        uint256 len = users.length;
        require(len != 0, "Whitelistable: EMPTY_BATCH");
        require(len <= MAX_BATCH_SIZE_LIMIT, "Whitelistable: BATCH_TOO_LARGE");

        for (uint256 i = 0; i < len; i++) {
            _setFeeExempt(users[i], allowed);
        }
    }

    /**
     * @dev Shared fee-exempt write, reused by the single and batch setters.
     */
    function _setFeeExempt(address user, bool allowed) private {
        require(user != address(0), "Whitelistable: ZERO_ADDRESS");
        require(allowed != feeExempt[user], "Whitelistable: ALREADY_SET");

        feeExempt[user] = allowed;
        emit FeeExemptSet(user, allowed);
    }

    /**
     * @dev Set whether a user can add liquidity while lpAllowlistOn is true.
     * @param user User address.
     * @param allowed LP allowlist flag.
     */
    function setLpAllowlist(address user, bool allowed) external onlyAdmin {
        require(user != address(0), "Whitelistable: ZERO_ADDRESS");
        require(allowed != lpAllowlist[user], "Whitelistable: ALREADY_SET");

        lpAllowlist[user] = allowed;
        emit LpAllowlistSet(user, allowed);
    }

    /**
     * @dev Toggle fee-exempt checks globally.
     */
    function setFeeExemptOn(bool on) external onlyAdmin {
        feeExemptOn = on;
        emit FeeExemptOnSet(on);
    }

    /**
     * @dev Toggle LP allowlist checks globally.
     */
    function setLpAllowlistOn(bool on) external onlyAdmin {
        lpAllowlistOn = on;
        emit LpAllowlistOnSet(on);
    }

    /**
     * @dev Effective fee-exempt check.
     */
    function isFeeExempt(address user) public view virtual returns (bool) {
        return feeExemptOn && feeExempt[user];
    }

    /**
     * @dev Effective LP allowlist check.
     */
    function isLpAllowed(address user) public view virtual returns (bool) {
        return !lpAllowlistOn || lpAllowlist[user];
    }
}

